# Code generated by Claude
"""
Tests of the hollow beaker (src/beaker.py, BEAKER_CFG in src/task_config.py) and of the contact friction it gets.

    python experiments/beaker_hollow_test.py

No viewer, no rendering, one model without cameras. Nothing is simulated: the beaker is placed with its free joint and the contacts that mj_forward finds are read.
1. The model: 24 box segments and a bottom disk that collide, a liquid mass that does not, the 70 x 100 mm outside, 2 mm walls, glass 100 g + liquid 100 g,
   the centre of mass and the inertia that follow, the site "beaker_base" at the bottom centre.
2. The friction of the contacts (the friction MuJoCo uses in the contact, read from data.contact):
   - every finger and palm geom of both hands against the beaker: 0.4 (150 explicit pairs);
   - the beaker on the bench: 1.2 (the beaker's 1.0 against the bench's 1.2, the higher), on the hotplate: 1.0, as before;
   - another robot geom (an arm link) against the beaker: 1.0 (the link's own, as before): only the gripper pairs changed.
"""

import math
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src.beaker import beaker_dims  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import BEAKER_CFG, TASK_CFG  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def contacts_of(m, d, body_a, body_b_pred):
    """Contacts between the geoms of body `body_a` and geoms whose body satisfies `body_b_pred`: [(geom name a, geom name b, friction[0])]."""
    out = []
    for i in range(d.ncon):
        c = d.contact[i]
        ba, bb = int(m.geom_bodyid[c.geom1]), int(m.geom_bodyid[c.geom2])
        for x, y, ga, gb in ((ba, bb, c.geom1, c.geom2), (bb, ba, c.geom2, c.geom1)):
            if x == body_a and body_b_pred(m.body(y).name):
                out.append((m.geom(gb).name, m.geom(ga).name, round(float(c.friction[0]), 4)))
                break
    return out


def place_beaker(m, d, pos):
    adr = m.joint("task_beaker_free").qposadr[0]
    d.qpos[adr:adr + 7] = [*pos, 1, 0, 0, 0]
    d.qvel[:] = 0.0
    mujoco.mj_forward(m, d)


def main():
    sim = load_task(cameras=False)
    m, d = sim.model, sim.data
    cfg = BEAKER_CFG
    dim = beaker_dims(cfg)
    b = m.body("task_beaker").id
    geoms = [g for g in range(m.ngeom) if int(m.geom_bodyid[g]) == b]
    name = lambda g: m.geom(g).name
    colliding = [g for g in geoms if m.geom_contype[g] or m.geom_conaffinity[g]]
    walls = [g for g in colliding if "_wall_" in name(g)]
    print("\n1. the model")
    check("24 box segments and one bottom disk collide", len(walls) == cfg["n_segments"] == 24 and len(colliding) == 25 and all(m.geom_type[g] == mujoco.mjtGeom.mjGEOM_BOX for g in walls),
          f"{len(walls)} walls, {len(colliding)} colliding geoms")
    liquid = m.geom("task_beaker_liquid").id
    check("the liquid is a mass only: no collision, invisible", not (m.geom_contype[liquid] or m.geom_conaffinity[liquid]) and m.geom_rgba[liquid][3] == 0.0)
    check("the solid fallback cylinder is gone", mujoco.mj_name2id(m, mujoco.mjtObj.mjOBJ_GEOM, "task_beaker_glass") < 0)
    total = float(m.body_mass[b])
    check("total mass = glass + liquid = 0.2 kg", abs(total - (cfg["glass_mass"] + cfg["liquid_mass"])) < 1e-9, f"{total:.6f} kg")
    empty = load_task(cameras=False, beaker_cfg={**cfg, "liquid_mass": 0.0})            # a second model: the same beaker without the liquid
    me = empty.model
    be = me.body("task_beaker").id
    check("an empty beaker (liquid_mass 0): no liquid geom, the glass alone is 100 g with its centre of mass at 43 mm",
          mujoco.mj_name2id(me, mujoco.mjtObj.mjOBJ_GEOM, "task_beaker_liquid") < 0 and abs(float(me.body_mass[be]) - cfg["glass_mass"]) < 1e-9 and 0.040 < me.body_ipos[be][2] < 0.046,
          f"{float(me.body_mass[be]):.6f} kg, centre of mass {1000 * me.body_ipos[be][2]:.1f} mm")
    del empty, me
    check("the liquid column of 100 g of water is 29.2 mm and sits on the bottom disk", abs(dim["liquid_h"] - 0.0292) < 5e-5 and abs(2 * m.geom_size[liquid][1] - dim["liquid_h"]) < 1e-9
          and abs(m.geom_pos[liquid][2] - (dim["bottom"] + dim["liquid_h"] / 2)) < 1e-9, f"{1000 * dim['liquid_h']:.2f} mm, centre {1000 * m.geom_pos[liquid][2]:.1f} mm above the base")
    com = float(m.body_ipos[b][2])
    check("centre of mass about 30 mm above the base (the old solid beaker: 50 mm)", 0.028 < com < 0.032 and abs(m.body_ipos[b][0]) < 1e-9 and abs(m.body_ipos[b][1]) < 1e-9, f"{1000 * com:.1f} mm")
    I = m.body_inertia[b]
    check("inertia: two equal moments about the horizontal axes, a smaller one about the vertical", abs(I[0] - I[1]) < 1e-8 and I[2] < I[0], np.array2string(I, formatter={"float_kind": lambda v: f"{v:.3e}"}) + " kg m^2")
    # outer size from the geoms' corners
    place_beaker(m, d, (0.0, 0.0, 5.0))
    pts = []
    for g in walls:
        R = d.geom_xmat[g].reshape(3, 3)
        half = m.geom_size[g]
        for sx in (-1, 1):
            for sy in (-1, 1):
                for sz in (-1, 1):
                    pts.append(d.geom_xpos[g] + R @ (np.array([sx, sy, sz]) * half))
    pts = np.array(pts)
    rad = np.hypot(pts[:, 0], pts[:, 1])
    zmin, zmax = pts[:, 2].min() - 5.0, pts[:, 2].max() - 5.0
    check("the walls are 100 mm tall (from the bottom disk's top to the rim, the disk below)", abs(zmax - cfg["height"]) < 1e-6 and abs(zmin - cfg["wall"]) < 1e-6, f"rim at {1000 * zmax:.2f} mm")
    check("outer diameter 70 mm (the box corners stick out 0.3 mm a side)", abs(2 * rad.max() - cfg["outer_diameter"]) < 0.0007 and rad.min() > dim["r_in"] - 0.0006,
          f"outer {2000 * rad.max():.2f} mm, inner {2000 * rad.min():.2f} mm")
    check("the site beaker_base is at the body origin (the bottom centre)", np.allclose(m.site("beaker_base").pos, 0.0))
    check("150 explicit contact pairs: 2 hands x 3 gripper geoms x 25 beaker geoms", m.npair == 150, f"{m.npair}")

    print("\n2. the friction MuJoCo uses in the contacts")
    gripper_geoms = [f"openarm_{sd}_{g}" for sd in ("left", "right") for g in cfg["gripper_geoms"]]
    for gname in gripper_geoms:
        g = m.geom(gname).id
        place_beaker(m, d, tuple(d.geom_xpos[g] - [0, 0, 0.05]))                  # the beaker's axis through the geom: they overlap
        cs = [c for c in contacts_of(m, d, b, lambda n: True) if c[0] == gname]
        fr = {c[2] for c in cs}
        check(f"{gname} against the beaker: friction 0.4", cs and fr == {0.4}, f"{len(cs)} contacts, friction {sorted(fr)}")
    link = m.geom("openarm_left_link5_collision").id
    place_beaker(m, d, tuple(d.geom_xpos[link] - [0, 0, 0.05]))
    cs = [c for c in contacts_of(m, d, b, lambda n: True) if c[0] == "openarm_left_link5_collision"]
    check("an arm link against the beaker: 1.0 (its own, unchanged)", cs and {c[2] for c in cs} == {1.0}, f"{len(cs)} contacts, friction {sorted({c[2] for c in cs})}")
    top = d.geom_xpos[m.geom("bench_top").id][2] + m.geom_size[m.geom("bench_top").id][2]
    place_beaker(m, d, (0.0, 0.0, top - 0.0005))
    cs = [c for c in contacts_of(m, d, b, lambda n: n == "bench")]
    check("the beaker on the bench: 1.2 (the higher of 1.0 and 1.2, as before)", cs and {c[2] for c in cs} == {1.2}, f"{len(cs)} contacts, friction {sorted({c[2] for c in cs})}")
    hp = d.geom_xpos[m.geom("task_hotplate_top_plate").id]
    htop = hp[2] + m.geom_size[m.geom("task_hotplate_top_plate").id][2]
    place_beaker(m, d, (hp[0], hp[1], htop - 0.0005))
    cs = [c for c in contacts_of(m, d, b, lambda n: n == "task_hotplate")]
    check("the beaker on the hotplate: 1.0, as before", cs and {c[2] for c in cs} == {1.0}, f"{len(cs)} contacts, friction {sorted({c[2] for c in cs})}")
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
